import{_ as t,H as i,f as a,i as s}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"15 | 非典型数据库故障解析：数据库故障一定是数据库的锅吗？","description":"","frontmatter":{},"headers":[{"level":2,"title":"背景介绍","slug":"背景介绍","link":"#背景介绍","children":[]},{"level":2,"title":"怎么分析数据库 CPU 使用率高的问题？","slug":"怎么分析数据库-cpu-使用率高的问题","link":"#怎么分析数据库-cpu-使用率高的问题","children":[{"level":3,"title":"优先恢复业务","slug":"优先恢复业务","link":"#优先恢复业务","children":[]}]},{"level":2,"title":"全量 SQL 分析","slug":"全量-sql-分析","link":"#全量-sql-分析","children":[]},{"level":2,"title":"故障再次发生","slug":"故障再次发生","link":"#故障再次发生","children":[]},{"level":2,"title":"从业务链路上来看问题","slug":"从业务链路上来看问题","link":"#从业务链路上来看问题","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"MySQL运维实战课/15｜非典型数据库故障解析：数据库故障一定是数据库的锅吗？.md","filePath":"MySQL运维实战课/15｜非典型数据库故障解析：数据库故障一定是数据库的锅吗？.md","lastUpdated":1795532766000}'),n={name:"MySQL运维实战课/15｜非典型数据库故障解析：数据库故障一定是数据库的锅吗？.md"};function l(r,e,o,E,p,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_15-非典型数据库故障解析-数据库故障一定是数据库的锅吗" tabindex="-1">15 | 非典型数据库故障解析：数据库故障一定是数据库的锅吗？ <a class="header-anchor" href="#_15-非典型数据库故障解析-数据库故障一定是数据库的锅吗" aria-label="Permalink to &quot;15 | 非典型数据库故障解析：数据库故障一定是数据库的锅吗？&quot;">​</a></h1><p>你好，我是俊达。</p><p>在前两讲中，我分别介绍了 MySQL 和 Linux 操作系统问题排查的基本思路，提供了一些判断数据库和操作系统是否有问题的方法。这一讲我们就以一个生产环境中发生的故障为例，来看看怎么运用前面讲到的基本方法，来分析和定位真实环境下的问题。</p><h2 id="背景介绍" tabindex="-1">背景介绍 <a class="header-anchor" href="#背景介绍" aria-label="Permalink to &quot;背景介绍&quot;">​</a></h2><p>这是我们公司服务的一家客户在线业务系统中发生的故障。这家客户提供在线支付业务，大量的消费者日常都会使用到这项服务。比如我们中午或傍晚到店里扫码点餐付款时，或者在商场里扫码付款时，都可能会用到这项服务。当时，我们给这家公司提供了数据库运维保障的服务。客户的核心业务数据库采用了国内头部的一家云厂商提供的 RDS for MySQL 产品。</p><p>有一天下午，快接近 6 点钟的时候，短促的告警声打破了办公室的平静，客户的告警通知群里面，出现了大量的实例 CPU 和活跃会话数的告警消息。通过监控大屏，我们发现问题都出在一个核心数据库上，数据库实例的 CPU 资源，几乎在瞬间达到了 100%。同时客户也反馈，业务端有大量的付款失败了。</p><h2 id="怎么分析数据库-cpu-使用率高的问题" tabindex="-1">怎么分析数据库 CPU 使用率高的问题？ <a class="header-anchor" href="#怎么分析数据库-cpu-使用率高的问题" aria-label="Permalink to &quot;怎么分析数据库 CPU 使用率高的问题？&quot;">​</a></h2><p>对于数据库 CPU 使用率打满的问题，一般我们都会先从实例中运行的 SQL 入手。有两种情况都可能会导致 CPU 打满，一种情况是实例中运行了执行效率特别低的 SQL，如大表全表扫描、大表连接并且缺少合适的连接条件或连接索引。另外一种情况是 SQL 的执行频率太高了。更差的情况是，SQL 效率很低，同时执行的并发量还很高。</p><p>一般我们会先到 PROCESSLIST 和慢 SQL 日志中找可疑的 SQL。但是 PROCESSLIST 只是实例所有会话的一个快照，如果 SQL 执行的时间比较长，那么在 PROCESSLIST 中看到这个SQL 的概率就比较高，但是对于执行时间没那么长的 SQL，你很可能就看不到。</p><p>而慢查询日志，只有查询的执行时间超过 long_query_time 后，才会记录下来。有时候我们需要分析全量 SQL，才能精确定位问题。各大云厂商提供的 RDS 产品，通常会提供 SQL 审计功能，将实例中执行的每一条 SQL 都记录下来，我们可以充分利用全量 SQL 审计日志，来分析某一个时间数据库中运行的 SQL。</p><p>此外，对于 CPU 使用率突变的情况，我们还要找到是什么原因导致了 SQL 的执行情况发生突变。一般我们可以先从以下几个方面来考虑。</p><ul><li><p>业务上有没有做推广引流，是不是有什么活动？</p></li><li><p>是不是触发了平时不怎么执行的一些 SQL，比如后台人员在对账，或者大数据系统在大规模抽取数据，或者是有大商户操作了管理后台，执行了一些开销很大的 SQL，或者研发人员执行数据订正。</p></li><li><p>应用程序是不是发布了新的版本，修改了 SQL 代码，导致 SQL 性能变化？</p></li><li><p>是不是有 SQL 的执行计划发生了变化，导致原先效率还可以的 SQL，性能急剧下降？</p></li><li><p>有没有可能数据库底层的操作系统和硬件环境的异常导致性能抖动，从而引起 SQL 积压？</p></li></ul><p>在客户的这次故障中，我们排除了上面所有的可能性。由于使用了 RDS，我们没有底层操作系统的权限，但是云厂商的工程师也参与到了故障分析中，他们确认了底层操作系统和硬件并没有问题。而且分析之后，我们也没有发现特别明显的问题 SQL，ProcessList 中看到的都是平时也一直在运行的正常的业务 SQL。</p><h3 id="优先恢复业务" tabindex="-1">优先恢复业务 <a class="header-anchor" href="#优先恢复业务" aria-label="Permalink to &quot;优先恢复业务&quot;">​</a></h3><p>故障期间数据库还发生了几次自动切换，但是业务依然没有恢复正常。初步分析业务 SQL，也没有找到明确的问题。此时故障还在持续，每一分钟的故障时间，都会给业务造成直接的资金损失。既然数据切换之后也没有恢复，当时我们就把应用程序进行了重启。应用重启之后，业务就立刻恢复了正常。</p><p>这也是我们处理故障的一个原则，遇到故障时，快速收集故障现场必要的信息之后，即使无法迅速定位到故障的根本原因，也要在第一时间恢复业务的正常运行。</p><h2 id="全量-sql-分析" tabindex="-1">全量 SQL 分析 <a class="header-anchor" href="#全量-sql-分析" aria-label="Permalink to &quot;全量 SQL 分析&quot;">​</a></h2><p>当然，在故障恢复之后，我们需要找到引起故障的真正原因，因为只有定位到了根本原因，你才能避免下一次出现同样的故障。针对这次故障中的实例，已经启用了 RDS 产品提供的 SQL洞察和审计功能，我们使用这个功能对故障期间执行的 SQL 做了分析。我们分析了故障发生前，数据库中扫描行数、返回行数看起来比较高的一些 SQL，并对这些 SQL 进行了一些优化。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/2.png" alt=""></a></p><h2 id="故障再次发生" tabindex="-1">故障再次发生 <a class="header-anchor" href="#故障再次发生" aria-label="Permalink to &quot;故障再次发生&quot;">​</a></h2><p>虽然我们找到了一些 SQL，做了相应的优化，但实际上，这并不是引起故障的真正原因。在接下来几天的时间里，我们严密监控数据库的运行情况，这期间数据库运行得很平稳。然后，差不多离上次故障近 1 周的一个下午，也是在下午 5 点多的业务高峰期，又发生了类似的故障。有了上次的经验，客户先重启了应用系统，恢复了业务。</p><p>但是故障的根本原因是什么？这次必须找出来。我和几位 DBA 同事一起赶到客户现场，在一间会议室里，跟客户侧的技术负责人、架构师、运维和研发人员，一起分析问题。上次使用常规的分析方法并没有定位到故障的根本原因。我们遗漏了哪些关键信息呢？</p><p>针对这次故障，我重新梳理了一下思路。从 RDS 的监控指标中可以确认几点。</p><ol><li>数据库的 CPU 确实在极短的时间里，冲到了 100%。之后有短暂的回落，但是后面 CPU使用率又上升到了 100%，并且一直持续高位运行，直到最后重启了应用系统后才恢复正常。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/3.png" alt=""></a></p><ol start="2"><li>CPU 上涨的同时，数据库 SQL 执行量也差不多翻了一倍，时间上很吻合。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/4.png" alt=""></a></p><ol start="3"><li>在 CPU 使用率上升的同时，数据库连接数上涨了好几倍。因此我们认为，由于某种原因，应用程序在瞬间创建了大量连接并执行 SQL，超过了 MySQL 的承受能力，引起性能恶化。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/5.png" alt=""></a></p><p>但是我们跟客户确认过，当时并没有做任何推广活动，应用系统也没有任何发布、变更。虽然当时是一天内业务的一个高峰期，但正常的业务流量是逐渐上涨的，也不会说一下子就涨好几倍。</p><ol start="4"><li>我们再来看数据库的网络流量趋势图，和 CPU 使用率、QPS 等指标的变化趋势是完全一致的。</li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/6.png" alt=""></a></p><p>仔细观察上面这几个性能趋势图，可以发现有一个共同点，就是在指标暴涨之前，先有一个短暂的下跌的过程，这个过程很短，大概也就 10-20 秒的时间。实际上在上一次的故障中，我们也观察到了同样的现象。当时也对可能的原因做了一些思考，是不是数据库底层环境有性能抖动？但是云厂商的运维人员做了细致地排查后，排除了这种可能性。是不是应用程序的某些特定的逻辑引起的？我们和客户侧的技术人员进行了一些探讨，但也没找到确切的原因。是不是最终用户在那个时间点都不用这个系统了？我们想想也觉得可能性不大。</p><h2 id="从业务链路上来看问题" tabindex="-1">从业务链路上来看问题 <a class="header-anchor" href="#从业务链路上来看问题" aria-label="Permalink to &quot;从业务链路上来看问题&quot;">​</a></h2><p>我们跟客户侧的架构师一起，梳理了业务系统的部署结构和调用链路。下面这个架构图中，位于最上层的是负载均衡设备，会把来自用户的请求分发到 nginx，nginx 再把请求转到后端应用，后端应用还会通过 Web Service 调用一些服务接口，位于架构最底层的是 RDS 和Redis。这也是比较典型的一种 Web 应用部署架构。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/7.png" alt=""></a></p><p>要判断来自用户的请求量是否有大的变化，实际上可以看入口处负载均衡的调用量，也可以通过分析 nginx 的访问日志得到。通过这些日志，我们得到了第一个结论，就是来自用户的请求在故障发生的时间点前后，并没有发生明显的变化。</p><p>是不是链路上的某个应用内部发生了什么变化？</p><p>我询问了客户侧的参会人员，当天下午发生故障前，有没有对应用系统做过任何操作？当天肯定没有做应用发布。后来一位工程师反馈，当时他做了一个数据订正，订正的内容是删除了Redis 中的几个 Key。正常来说，删除缓存中的几个 Key，也不至于造成这么大的影响。我又详细询问了这位工程师，当时操作执行了哪些具体命令。工程师反馈说，他先通过 keyspattern 命令查找需要删除的 Key，然后再把这几个 Key 删除掉。</p><p>到这里，你可能已经知道问题出在哪里了。Redis 中执行 keys * 命令是非常危险的一个操作，如果 key 的数量比较多，keys * 命令可能需要执行很长的时间，更严重的是，执行期间会导致其他请求被阻塞。</p><p>这个客户的 Redis 没有在我们的服务范围内，因此我们也根本没有想过这方面的问题。听到工程师的反馈后，我们立刻查看了 Redis 的监控。在数据库流量下跌的同一个时间，Redis 的CPU 使用率有大幅度的上涨，最高达到了 100%。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/8.png" alt=""></a></p><p>看来对 Redis 的操作才是引起故障的真正原因。为了更好地理解这个问题，我画了一个程序访问的时序图。用户扫码付款时，应用程序请求某个 API，读取 Redis 中的一个 Key，但由于当时 Redis 在执行 keys * 命令，读取 Key 的请求就被阻塞了。</p><p>keys * 命令执行了十几秒，因此这十几秒里，调用这个接口的用户线程都需要等待。最终，keys * 命令执行完成，等待的用户线程都完成了接口调用，然后再调用其他接口，到 MySQL中执行 SQL。积压了十几秒的用户线程，几乎在同一个时间点连接数据库，执行 SQL，最终超出了数据库的承受能力，发生了故障。这和我们从前面几个监控图表中观察到的现象完全一致。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/9.png" alt=""></a></p><p>下面这个图可以更好地解释这个现象。应用程序发起的请求，先在 Redis 中积压了十几秒，然后又几乎在同一个时间点从 Redis 请求中返回，一瞬间，这些请求同时涌向了 MySQL，MySQL 不堪重负，发生了故障。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MySQL%E8%BF%90%E7%BB%B4%E5%AE%9E%E6%88%98%E8%AF%BE/images/15/10.png" alt=""></a></p><p>定位到最终问题后，我们和客户悬着的心终于放了下来。接下来，客户在内部进行了强调，禁止在线上执行危险的操作。对于 keys * 操作，也可以在 Redis 层面禁用掉。之后，就再也没有发生过这样的故障了。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在这个故障案例中，MySQL 的故障，由看起来毫不相关的一个 Redis 操作引起。这也警示了我们，在分析问题时，要从系统全局出发，不能局限在数据库内部。同时也要注意，在给一个问题下结论的时候，要多问问自己，这个问题真的是这个原因引起的吗？是不是能解释问题中的所有现象？</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>MySQL 中存在这么一个现象，平时执行得好好的 SQL，在数据库很繁忙的时候，执行效率也会变得很差，当然，这可以理解。你从 Processlist 或慢 SQL 日志中看到执行耗时比较长的SQL，其中有些是引起数据库性能问题的罪魁祸首，有些则是受害者。你应该怎么区分这两种情况，找到真正需要优化的那些 SQL 呢？</p><p>期待你的思考，欢迎在留言区中与我交流。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友。我们下节课再见！</p>',54)])])}const B=t(n,[["render",l]]);export{c as __pageData,B as default};
